<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';require_once dirname(__DIR__).'/app/UI/MessageHtml.php';require_once dirname(__DIR__).'/app/UI/Conversation.php';require_once dirname(__DIR__).'/app/Mail/Reception.php';
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self'; frame-src 'self'; img-src 'self' data: https:; form-action 'self'; base-uri 'none'; frame-ancestors 'self'");$db=tnl_db();$identity=\TNL\Auth\SessionUser::require($db);\TNL\Mail\Reception::init($db);$admin=$identity['role']==='admin';$message=null;if(isset($_GET['id'])){$message=\TNL\Mail\Reception::read($db,(int)$_GET['id'],$identity['id'],$admin);if(!$message){http_response_code(404);exit('Mensaje no disponible.');}}$q=$db->prepare('SELECT id,token,sender,subject,created_at,read_at FROM reception_messages'.($admin?'':' WHERE assigned_user=?').' ORDER BY id DESC LIMIT 100');$q->execute($admin?[]:[$identity['id']]);$groups=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $entry){if(!isset($groups[$entry['token']]))$groups[$entry['token']]=$entry+['unread_count'=>0];if($entry['read_at']===null)$groups[$entry['token']]['unread_count']++;}$messages=array_values($groups);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recepción asignada · TNL Mail</title><link rel="stylesheet" href="assets/app.css?v=0.12.0"><script src="assets/workspace.js?v=0.12.0" defer></script><script src="assets/composer.js?v=0.12.0" defer></script></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar($identity['role'],'reception-mail',$identity['name']);?><main class="main"><h1>Recepción asignada</h1><?php if($message):?><article class="panel message-panel"><header class="message-heading"><div><h2><?=tnl_escape($message['subject'])?></h2><p><?=tnl_escape($message['sender'].' · '.$message['created_at'])?></p></div><?php if(!$admin):?><a class="button" data-compose-modal href="mail.php?reception=<?=(int)$message['id']?>&amp;compose=1&amp;modal=1">Responder</a><?php endif;?></header></article><div data-live-region="reception-thread"><?php \TNL\UI\Conversation::render(\TNL\Mail\Reception::conversation($db,$message,$identity['id'],$admin,tnl_path('storage')),true);?></div><?php endif;?><section class="panel mail-surface" data-live-region="reception-list"><?php foreach($messages as $m):?><a class="mail-row" href="?id=<?=(int)$m['id']?>"><span><?=tnl_escape($m['sender'])?></span><span><?=tnl_escape($m['subject'])?><?=$m['unread_count']?' · '.(int)$m['unread_count'].' nuevos':''?></span><time><?=tnl_escape($m['created_at'])?></time></a><?php endforeach;?><?php if(!$messages):?><p class="empty-state">No hay mensajes asignados.</p><?php endif;?></section></main></div></body></html>
